fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // All three inputs are guaranteed to have the same length.
    let n = s1.len();
    // We reserve exactly 3n elements up front to avoid repeated reallocations.
    let mut res = Vec::with_capacity(n.checked_mul(3).expect("3*n must fit in usize"));

    for i in 0..n {
        // For each index i, push s1[i], then s2[i], then s3[i].
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}

